<html lang="ja">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>ブロック崩し | Breakout</title>
<style>
  :root {
    --bg: #0b0e1a;
    --panel: #141a2e;
    --accent: #4fc3f7;
    --text: #e6edf3;
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    background: var(--bg);
    color: var(--text);
    font-family: "Segoe UI", "Hiragino Sans", "Noto Sans JP", sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    min-height: 100vh;
    padding: 16px;
  }
  h1 {
    font-size: 1.4rem;
    letter-spacing: 0.1em;
    margin-bottom: 8px;
    color: var(--accent);
  }
  #hud {
    display: flex;
    gap: 24px;
    margin-bottom: 10px;
    font-size: 0.95rem;
  }
  #hud span b { color: var(--accent); }
  #game-wrap {
    position: relative;
    border: 2px solid #2a3555;
    border-radius: 8px;
    overflow: hidden;
    box-shadow: 0 0 40px rgba(79, 195, 247, 0.15);
  }
  canvas { display: block; background: #0d1222; }
  #overlay {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 14px;
    background: rgba(10, 14, 26, 0.82);
    backdrop-filter: blur(3px);
  }
  #overlay.hidden { display: none; }
  #overlay h2 { font-size: 1.6rem; }
  #overlay p { font-size: 0.9rem; opacity: 0.8; text-align: center; line-height: 1.7; }
  #overlay button {
    padding: 10px 28px;
    font-size: 1rem;
    border: none;
    border-radius: 6px;
    background: var(--accent);
    color: #06121e;
    cursor: pointer;
    font-weight: 700;
    transition: transform 0.1s;
  }
  #overlay button:hover { transform: scale(1.05); }
  #controls {
    margin-top: 10px;
    font-size: 0.8rem;
    opacity: 0.6;
  }
</style>
</head>
<body>
<h1>BLOCK BREAKER</h1>
<div id="hud">
  <span>SCORE <b id="score">0</b></span>
  <span>LEVEL <b id="level">1</b></span>
  <span>LIVES <b id="lives">3</b></span>
  <span>BEST <b id="best">0</b></span>
</div>
<div id="game-wrap">
  <canvas id="game" width="640" height="480"></canvas>
  <div id="overlay">
    <h2 id="overlay-title">ブロック崩し</h2>
    <p id="overlay-text">
      マウス / タッチ でパドルを操作<br>
      ← → キーでも操作できます<br>
      スペースでボール発射
    </p>
    <button id="start-btn">スタート</button>
  </div>
</div>
<div id="controls">マウス・タッチ / ←→キー: パドル移動 | スペース: ボール発射・一時停止</div>

<script>
(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;

  const scoreEl = document.getElementById('score');
  const levelEl = document.getElementById('level');
  const livesEl = document.getElementById('lives');
  const bestEl  = document.getElementById('best');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlay-title');
  const overlayText  = document.getElementById('overlay-text');
  const startBtn = document.getElementById('start-btn');

  const BLOCK_COLORS = ['#ef5350', '#ff9800', '#ffee58', '#66bb6a', '#42a5f5', '#ab47bc'];

  const state = {
    running: false,
    paused: false,
    score: 0,
    level: 1,
    lives: 3,
    best: Number(localStorage.getItem('breakout-best') || 0),
    blocks: [],
    ball: { x: 0, y: 0, r: 7, dx: 0, dy: 0, stuck: true, speed: 5 },
    paddle: { w: 100, x: W / 2 - 50, h: 12, y: H - 30 },
    particles: [],
    keys: { left: false, right: false },
  };
  bestEl.textContent = state.best;

  function buildLevel(level) {
    const rows = Math.min(4 + level, 8);
    const cols = 10;
    const padding = 4;
    const top = 50;
    const blockW = (W - padding * (cols + 1)) / cols;
    const blockH = 20;
    state.blocks = [];
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        // レベルに応じて一部ブロックを強固にする
        const tough = level >= 2 && (r + c) % 5 === 0;
        state.blocks.push({
          x: padding + c * (blockW + padding),
          y: top + r * (blockH + padding),
          w: blockW,
          h: blockH,
          color: BLOCK_COLORS[r % BLOCK_COLORS.length],
          hp: tough ? 2 : 1,
          points: (rows - r) * 10,
        });
      }
    }
  }

  function resetBall() {
    const p = state.paddle;
    state.ball.stuck = true;
    state.ball.x = p.x + p.w / 2;
    state.ball.y = p.y - state.ball.r - 1;
    state.ball.dx = 0;
    state.ball.dy = 0;
    state.ball.speed = 5 + (state.level - 1) * 0.6;
  }

  function launchBall() {
    if (!state.ball.stuck) return;
    const angle = (-Math.PI / 3) + Math.random() * (-Math.PI / 6);
    // -60度〜-90度の範囲で打ち出す
    const a = -(Math.PI / 2) + (Math.random() * 60 - 30) * Math.PI / 180;
    state.ball.dx = Math.cos(a) * state.ball.speed;
    state.ball.dy = Math.sin(a) * state.ball.speed;
    state.ball.stuck = false;
  }

  function spawnParticles(x, y, color) {
    for (let i = 0; i < 8; i++) {
      state.particles.push({
        x, y,
        dx: (Math.random() - 0.5) * 4,
        dy: (Math.random() - 0.5) * 4 - 1,
        life: 24,
        color,
      });
    }
  }

  function updateHud() {
    scoreEl.textContent = state.score;
    levelEl.textContent = state.level;
    livesEl.textContent = state.lives;
    if (state.score > state.best) {
      state.best = state.score;
      localStorage.setItem('breakout-best', state.best);
      bestEl.textContent = state.best;
    }
  }

  function collideBlock(b, i) {
    b.hp--;
    if (b.hp <= 0) {
      state.score += b.points;
      spawnParticles(b.x + b.w / 2, b.y + b.h / 2, b.color);
      state.blocks.splice(i, 1);
    } else {
      state.score += 5;
      b.color = '#78909c'; // 傷ついたブロックは灰色に
    }
    updateHud();
  }

  function update() {
    const p = state.paddle;
    const ball = state.ball;

    // パドル移動(キー)
    const pSpeed = 8;
    if (state.keys.left)  p.x -= pSpeed;
    if (state.keys.right) p.x += pSpeed;
    p.x = Math.max(0, Math.min(W - p.w, p.x));

    if (ball.stuck) {
      ball.x = p.x + p.w / 2;
      ball.y = p.y - ball.r - 1;
    } else {
      ball.x += ball.dx;
      ball.y += ball.dy;

      // 壁
      if (ball.x - ball.r < 0)   { ball.x = ball.r;     ball.dx = Math.abs(ball.dx); }
      if (ball.x + ball.r > W)   { ball.x = W - ball.r; ball.dx = -Math.abs(ball.dx); }
      if (ball.y - ball.r < 0)   { ball.y = ball.r;     ball.dy = Math.abs(ball.dy); }

      // 下に落ちた
      if (ball.y - ball.r > H) {
        state.lives--;
        updateHud();
        if (state.lives <= 0) {
          gameOver(false);
        } else {
          resetBall();
        }
        return;
      }

      // パドル
      if (
        ball.dy > 0 &&
        ball.y + ball.r >= p.y &&
        ball.y + ball.r <= p.y + p.h + ball.dy &&
        ball.x >= p.x - ball.r &&
        ball.x <= p.x + p.w + ball.r
      ) {
        // 当たった位置で反射角を決める
        const hit = (ball.x - (p.x + p.w / 2)) / (p.w / 2); // -1〜1
        const angle = -Math.PI / 2 + hit * (Math.PI / 3);   // 最大±60度
        const sp = Math.min(ball.speed + 0.15, 11);
        ball.speed = sp;
        ball.dx = Math.cos(angle) * sp;
        ball.dy = Math.sin(angle) * sp;
        ball.y = p.y - ball.r - 1;
      }

      // ブロック
      for (let i = state.blocks.length - 1; i >= 0; i--) {
        const b = state.blocks[i];
        if (
          ball.x + ball.r > b.x &&
          ball.x - ball.r < b.x + b.w &&
          ball.y + ball.r > b.y &&
          ball.y - ball.r < b.y + b.h
        ) {
          // どの面から当たったかで反射方向を決める
          const overlapX = Math.min(ball.x + ball.r - b.x, b.x + b.w - (ball.x - ball.r));
          const overlapY = Math.min(ball.y + ball.r - b.y, b.y + b.h - (ball.y - ball.r));
          if (overlapX < overlapY) ball.dx = -ball.dx;
          else ball.dy = -ball.dy;
          collideBlock(b, i);
          break;
        }
      }

      // 水平に走りすぎたとき補正(スタック防止)
      if (Math.abs(ball.dy) < 1 && !ball.stuck) {
        const s = Math.hypot(ball.dx, ball.dy) || ball.speed;
        const sign = ball.dy >= 0 ? 1 : -1;
        ball.dy = sign * 1.5;
        const nx = Math.sqrt(Math.max(0, s * s - ball.dy * ball.dy));
        ball.dx = Math.sign(ball.dx || 1) * nx;
      }
    }

    // パーティクル
    for (let i = state.particles.length - 1; i >= 0; i--) {
      const pt = state.particles[i];
      pt.x += pt.dx;
      pt.y += pt.dy;
      pt.dy += 0.15;
      pt.life--;
      if (pt.life <= 0) state.particles.splice(i, 1);
    }

    // 面クリア
    if (state.blocks.length === 0) {
      gameOver(true);
    }
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);

    // 背景のグリッド
    ctx.strokeStyle = 'rgba(80, 110, 180, 0.08)';
    ctx.lineWidth = 1;
    for (let x = 0; x < W; x += 32) {
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, H); ctx.stroke();
    }
    for (let y = 0; y < H; y += 32) {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke();
    }

    // ブロック
    for (const b of state.blocks) {
      ctx.fillStyle = b.color;
      ctx.globalAlpha = b.hp >= 2 ? 1 : 0.85;
      ctx.fillRect(b.x, b.y, b.w, b.h);
      ctx.globalAlpha = 1;
      ctx.fillStyle = 'rgba(255,255,255,0.25)';
      ctx.fillRect(b.x, b.y, b.w, 3);
    }

    // パドル
    const p = state.paddle;
    const grad = ctx.createLinearGradient(p.x, p.y, p.x, p.y + p.h);
    grad.addColorStop(0, '#81d4fa');
    grad.addColorStop(1, '#0288d1');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.roundRect(p.x, p.y, p.w, p.h, 6);
    ctx.fill();

    // ボール
    ctx.fillStyle = '#fff';
    ctx.shadowColor = '#4fc3f7';
    ctx.shadowBlur = 12;
    ctx.beginPath();
    ctx.arc(state.ball.x, state.ball.y, state.ball.r, 0, Math.PI * 2);
    ctx.fill();
    ctx.shadowBlur = 0;

    // パーティクル
    for (const pt of state.particles) {
      ctx.globalAlpha = pt.life / 24;
      ctx.fillStyle = pt.color;
      ctx.fillRect(pt.x - 2, pt.y - 2, 4, 4);
    }
    ctx.globalAlpha = 1;

    // 一時停止表示
    if (state.paused && state.running) {
      ctx.fillStyle = 'rgba(230, 237, 243, 0.9)';
      ctx.font = 'bold 28px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('PAUSED', W / 2, H / 2);
      ctx.textAlign = 'left';
    }
  }

  function loop() {
    if (state.running && !state.paused) update();
    draw();
    requestAnimationFrame(loop);
  }

  function showOverlay(title, text, btnLabel) {
    overlayTitle.textContent = title;
    overlayText.innerHTML = text;
    startBtn.textContent = btnLabel;
    overlay.classList.remove('hidden');
  }

  function gameOver(cleared) {
    state.running = false;
    updateHud();
    if (cleared) {
      state.level++;
      showOverlay(
        `レベル ${state.level - 1} クリア!`,
        `スコア: ${state.score}<br>次のレベルへ!`,
        'つぎへ'
      );
    } else {
      showOverlay(
        'ゲームオーバー',
        `スコア: ${state.score}<br>ベスト: ${state.best}`,
        'もう一度'
      );
    }
  }

  function startGame(advanceLevel) {
    if (!advanceLevel) {
      state.score = 0;
      state.level = 1;
      state.lives = 3;
    }
    state.paddle.w = Math.max(70, 100 - (state.level - 1) * 6);
    state.paddle.x = W / 2 - state.paddle.w / 2;
    state.particles = [];
    buildLevel(state.level);
    resetBall();
    updateHud();
    state.running = true;
    state.paused = false;
    overlay.classList.add('hidden');
  }

  // --- 入力 ---
  startBtn.addEventListener('click', () => {
    const advance = state.running === false && state.lives > 0 && state.blocks.length === 0 && state.score > 0;
    startGame(advance);
  });

  canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = (e.clientX - rect.left) * (W / rect.width);
    state.paddle.x = Math.max(0, Math.min(W - state.paddle.w, x - state.paddle.w / 2));
  });

  canvas.addEventListener('touchmove', (e) => {
    e.preventDefault();
    const rect = canvas.getBoundingClientRect();
    const x = (e.touches[0].clientX - rect.left) * (W / rect.width);
    state.paddle.x = Math.max(0, Math.min(W - state.paddle.w, x - state.paddle.w / 2));
  }, { passive: false });

  canvas.addEventListener('click', () => launchBall());

  document.addEventListener('keydown', (e) => {
    if (e.code === 'ArrowLeft')  state.keys.left = true;
    if (e.code === 'ArrowRight') state.keys.right = true;
    if (e.code === 'Space') {
      e.preventDefault();
      if (state.running) {
        if (state.ball.stuck) launchBall();
        else state.paused = !state.paused;
      } else if (!overlay.classList.contains('hidden')) {
        startBtn.click();
      }
    }
  });
  document.addEventListener('keyup', (e) => {
    if (e.code === 'ArrowLeft')  state.keys.left = false;
    if (e.code === 'ArrowRight') state.keys.right = false;
  });

  buildLevel(1);
  resetBall();
  loop();
})();
</script>
</body>
</html>
